import {backupMarkup,mountBackup,persistBackupRestore,downloadBackupFile} from './backup-ui.js';
import {exportProfileBackup} from './backup-model.js';
import {createLearningStorage} from './storage-coordinator.js';
import {parseDialogueRoute,dialogueMarkup,mountDialogue} from './dialogue-page.js';
import {isLoopSubject,startLoop,getLoop,loopAction,loopEvidence} from './loop-model.js';
import {loopMarkup,reviewMarkup,loopParentMarkup,loopWrongsMarkup} from './loop-ui.js';
import {attachVideoControls} from './video-controls.js';
import {subjects,item,select,hint,advance,units,saveStore,currentProfile,switchProfile,clearProfile,getPractice,practiceAttempt,finishPractice,questionById,retryWrong,startTest,chooseTest,submitTest,testResults,testCursor,navigateTest} from './model.js';
const main=document.querySelector('#main'),info=document.querySelector('#info');
let disposeDialogue=null,disposeBackup=null,pendingTest=null;
let storageBlocked=false,conflictReady=false,reloading=false,conflictReason='';
let disposeVideo=null,guideTab='hints',practiceViewKey='',resultTest=null,resultIndex=0;
function setView(markup,learning=false){if(storageBlocked)return;disposeBackup?.();disposeBackup=null;disposeDialogue?.();disposeDialogue=null;disposeVideo?.();disposeVideo=null;document.body.dataset.layout=learning?'learning':'reading';main.innerHTML=markup;}
const videoPositions=new Map();
function mountVideo(key='standalone'){if(storageBlocked)return;const video=main.querySelector('video');const cleanup=attachVideoControls({video,source:main.querySelector('source'),backward:main.querySelector('#video-backward'),toggle:main.querySelector('#video-toggle'),forward:main.querySelector('#video-forward'),icon:main.querySelector('#video-toggle-icon'),label:main.querySelector('#video-toggle-label'),time:main.querySelector('#video-time'),status:main.querySelector('#video-status'),error:main.querySelector('#video-error')});let restored=false;const restore=()=>{if(restored||!Number.isFinite(video.duration)||video.duration<=0)return;restored=true;const position=videoPositions.get(key);if(position>0){try{video.currentTime=Math.min(position,video.duration);}catch{}}};video.addEventListener('loadedmetadata',restore);restore();disposeVideo=()=>{if(Number.isFinite(video.currentTime))videoPositions.set(key,video.currentTime);video.removeEventListener('loadedmetadata',restore);cleanup();};}
let nativeStorage;try{nativeStorage=window.localStorage;}catch{nativeStorage=null;}
const coordinator=createLearningStorage({storage:nativeStorage,onBlocked:onStorageBlocked}),storage=coordinator.storage;
const loaded=coordinator.load();let store=loaded.store,warning=loaded.warning,session=null,retryId=null,retryChoice=null,retryFeedback=null,testMessage='';
const persist=()=>{if(!canAct())return false;warning=saveStore(storage,store);renderProfile();return !warning;};
function stopActiveWork(){const cleanups=[disposeBackup,disposeDialogue,disposeVideo];disposeBackup=disposeDialogue=disposeVideo=null;pendingTest=null;for(const cleanup of cleanups){try{cleanup?.();}catch{}}}
function onStorageBlocked(state){storageBlocked=true;conflictReason=state.reason;stopActiveWork();if(conflictReady)showStorageConflict();}
function showStorageConflict(forceFocus=false){
 if(!storageBlocked||!conflictReady||reloading)return;
 stopActiveWork();try{main.inert=true;document.querySelector('#profile-controls').inert=true;document.querySelector('.shell').inert=true;}catch{}
 for(const id of ['#clear-confirm','#replace-test','#info']){const dialog=document.querySelector(id);if(dialog?.open){try{dialog.close();}catch{}}}
 document.querySelector('#storage-conflict-detail').textContent=conflictReason==='read-failed'?'现在无法核对浏览器中已保存的记录，本页已停止继续保存。':'检测到本机已保存的记录发生变化，本页已停止继续保存。';
 document.querySelector('#storage-conflict-current').textContent=`本页当前停留在档案 ${store.current}。`;
 const dialog=document.querySelector('#storage-conflict');const visible=dialog.open||dialog.getAttribute?.('data-fallback')==='true';if(!visible){try{dialog.showModal();}catch{dialog.setAttribute('open','');dialog.setAttribute('data-fallback','true');}forceFocus=true;}if(forceFocus){try{document.querySelector('#storage-conflict-title').focus({preventScroll:true});}catch{}}
}
function canAct(){if(storageBlocked){showStorageConflict(true);return false;}return coordinator.check();}

function renderProfile(){const displayWarning=coordinator.getState().mode==='temporary'?'当前仅能在本页临时学习，此页不会写回浏览器存储。请先在家长页分别下载需要保留的档案临时备份，再重新载入页面检查存储；重新载入会丢失未备份的临时记录。':warning;document.querySelector('#profile-controls').innerHTML=`<div class="profile-row"><div><strong>当前：学习档案 ${store.current}</strong><span class="profile-options">${['A','B'].map(k=>`<button class="profile-switch ${store.current===k?'active':''}" data-profile="${k}" aria-pressed="${store.current===k}">档案 ${k}</button>`).join('')}</span></div><div class="profile-tools"><button class="text-button compact-notice" data-open-info>本机保存 · 说明</button><button class="text-button" id="clear-profile">清除此档案</button></div></div><p class="local-notice">记录只保存在此浏览器，清除浏览器数据可能丢失，不跨设备同步。档案仅用于分组，不是账号或身份验证。</p>${displayWarning?`<p class="storage-warning" role="alert">${esc(displayWarning)}</p>`:''}`;}

const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function focusMain(){if(storageBlocked){showStorageConflict();return;}main.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
function home(){setView(`<section class="loop-entry"><div><span class="chip">新 · 本地规则模拟</span><h2>小步引导：试一题，想两步，再练新题</h2><p>固定原创题库 · 未接 DeepSeek · 首次选择与引导后结果分别保留</p></div><div class="loop-entry-actions">${['math','chinese','english'].map(k=>`<a class="primary" href="#loop/${k}">${subjects[k].label}小步引导 →</a>`).join('')}<a class="secondary" href="#reviews">本地复习安排</a></div></section><div class="hero"><div><p class="eyebrow">SMALL STEPS · BIG DISCOVERIES</p><h1>从一道题开始，<br><span><span class="phrase">把「不会」</span><span class="phrase">变成「我试试」。</span></span></h1><p>先自己想一想，需要时再看提示。<br>不用赶时间，我们一步一步来。</p></div><div class="scene" aria-hidden="true"><span class="shape shape-a">字</span><span class="shape shape-b">÷</span><span class="shape shape-c">Aa</span></div></div><div class="section-title"><h2>今天，想先试哪一科？</h2><span>每组 2 题 · 约 2 分钟</span></div><div class="subjects">${Object.entries(subjects).map(([key,s])=>`<button class="subject ${key}" data-subject="${key}"><span class="symbol" aria-hidden="true">${s.symbol}</span><h3>${s.label}</h3><p>${s.topic}</p><span class="arrow" aria-hidden="true">→</span></button>`).join('')}</div><div class="flow-note"><strong>先试一题 → 按需看提示 → 再试一道新题</strong><span>原创示例 · 本浏览器保存 · 未接教材或模型</span></div><div class="learning-grid"><a class="feature-card video-card" href="#video"><span class="feature-icon" aria-hidden="true">▶</span><div><small>约 1 分钟 · 普通话配音 + 字幕</small><h2>平均分 · 视频讲解</h2><p>跟着糖果动画，看看怎样分得一样多。</p></div><span aria-hidden="true">→</span></a><a class="feature-card" href="#assessments"><h2>单元测评</h2><p>3 个原创示例单元 · 每单元 4 题</p><span>独立作答，交卷后看解析 →</span></a><a class="feature-card" href="#wrongs"><h2>错题记录</h2><p>保留每次错误，再试一次，看见订正。</p><span>打开当前档案的错题 →</span></a></div><section class="voice-plan"><div><h2>题目对话与语音 <span class="chip">本地示例</span></h2><p>先用固定题试试文字追问。本机识别与朗读仅在浏览器支持时启用；DeepSeek 尚未接通，不会向服务商发送提问。</p></div><a class="secondary" href="#dialogue/math/0">打开题目对话 →</a></section>`);}
function videoMarkup(){return `<div class="media-frame"><video id="lesson-video" class="lesson-video" controls playsinline preload="metadata" poster="/media/average-sharing-poster.jpg" aria-label="平均分视频讲解"><source src="/media/average-sharing.mp4" type="video/mp4">浏览器暂不支持播放视频。</video></div><div class="video-controls-panel"><div class="video-controls" role="group" aria-label="视频大按钮"><button type="button" id="video-backward" class="video-control" aria-label="快退 5 秒" aria-controls="lesson-video" disabled><span class="video-control-icon" aria-hidden="true">↶</span><span>快退 5 秒</span></button><button type="button" id="video-toggle" class="video-control video-control-main" data-state="paused" aria-label="播放视频" aria-controls="lesson-video" disabled><span id="video-toggle-icon" class="video-control-icon" aria-hidden="true"></span><span id="video-toggle-label">播放</span></button><button type="button" id="video-forward" class="video-control" aria-label="快进 5 秒" aria-controls="lesson-video" disabled><span class="video-control-icon" aria-hidden="true">↷</span><span>快进 5 秒</span></button></div><div class="video-control-details"><p id="video-status" role="status" aria-live="polite" aria-atomic="true">正在准备视频…</p><span id="video-time" class="video-time" aria-label="播放进度">00:00 / --:--</span></div><p class="video-control-tip">点大按钮操作 · 全屏请用视频里的按钮</p></div><p id="video-error" class="storage-warning" hidden>视频暂时未能加载，请稍后重试。也可以继续做题。</p>`;}
function workspaceHeading(title,subtitle,back='<button class="back" data-action="leave">← 选科首页</button>'){return `<div class="workspace-heading">${back}<div><h1>${title}</h1><p>${subtitle}</p></div></div>`;}
function renderPractice(){
 const s=session,subject=subjects[s.subject],q=item(s),r=s.records[s.stage],key=`${store.current}:${s.id}:${s.stage}`;
 if(practiceViewKey!==key){guideTab='hints';practiceViewKey=key;}
 const hasVideo=s.subject==='math',canGuide=r.attempts>0;
 if(!hasVideo||!canGuide)guideTab='hints';
 const guide=guideTab==='video'?`<div class="practice-video">${videoMarkup()}</div><p class="guide-caption">平均分的原创示例：12 颗糖分给 3 人。可以暂停，对照这道题想一想。</p>`:r.solved?`<div class="guide-explanation"><span class="guide-symbol" aria-hidden="true">✓</span><h2>一起看看为什么</h2><p>${esc(q.explanation)}</p><p class="muted">再用自己的话说一遍，你是怎么想的？</p></div>`:r.hints?`<div class="hint-stack" role="status">${q.hints.slice(0,r.hints).map((text,i)=>`<div class="hint"><strong>小提示 ${i+1} / 3</strong><p>${esc(text)}</p></div>`).join('')}</div>`:`<div class="guide-welcome"><span class="guide-symbol" aria-hidden="true">${subject.symbol}</span><h2>${canGuide?'卡住了也没关系':'先自己想一想'}</h2><p>${canGuide?'一次打开一个小提示，再回到题目试一试。':'选一个答案，点「检查答案」。也可以点「我还不会」，再看看提示。'}</p><p class="muted">${hasVideo?'尝试后，可以在这里切换提示和视频，不用离开题目。':'提示会在这里展开，不用离开题目。'}</p></div>`;
 setView(`<div class="learning-workspace practice-workspace">${workspaceHeading(subject.label+' · '+subject.tag,`第 ${s.stage+1} / 2 题 · ${s.stage?'换一道新题':'先自己试一试'}`)}<div class="workspace-grid"><section class="question-card work-question" aria-label="当前题目"><div class="question-content"><div class="question-meta"><span class="chip">${subject.label}练习</span><span>第 ${s.stage+1} 题</span></div><h2 class="question-title" tabindex="-1">${esc(q.question)}</h2>${!r.solved?'<p class="instruction">选好后点「检查答案」。答错也没关系。</p>':''}<div class="choices" role="group" aria-label="选择答案">${q.choices.map((c,i)=>`<button class="choice ${s.selected===c?'selected':''}" data-choice="${esc(c)}" aria-pressed="${s.selected===c}" ${r.solved?'disabled':''}><span>${String.fromCharCode(65+i)}</span><strong>${esc(c)}</strong></button>`).join('')}</div><div id="feedback" aria-live="polite">${s.feedback?`<div class="feedback ${s.feedback==='correct'?'good':''}"><strong>${s.feedback==='correct'?'答对了，继续保持好奇心！':'没关系，再想一想。'}</strong></div>`:''}</div></div><div class="question-actions">${r.solved?`<span class="muted">${s.stage?'这组练习完成啦':'准备好再往前走'}</span><button class="primary" data-action="next">${s.stage?'看看这次的小结':'试一道新题'} →</button>`:`<button class="text-button" data-action="skip">我还不会</button><button class="primary" data-action="submit" ${s.selected===null?'disabled':''}>检查答案</button>`}</div></section><aside class="guide-pane" aria-label="解题帮助"><div class="guide-tabs" role="tablist" aria-label="解题方式"><button id="guide-hints" role="tab" aria-selected="${guideTab==='hints'}" aria-controls="guide-panel" tabindex="${guideTab==='hints'?0:-1}" class="guide-tab" data-guide="hints">${r.solved?'解题思路':'思路提示'}</button>${hasVideo?`<button id="guide-video" role="tab" aria-selected="${guideTab==='video'}" aria-controls="guide-panel" tabindex="${guideTab==='video'?0:-1}" class="guide-tab" data-guide="video" ${!canGuide?'disabled':''}>视频讲解</button>`:''}</div><div id="guide-panel" class="guide-content ${guideTab==='video'?'guide-video-content':''}" role="tabpanel" aria-labelledby="guide-${guideTab}" tabindex="0">${guide}</div>${guideTab==='hints'&&!r.solved?`<div class="guide-actions"><span>${!canGuide?'先尝试，再打开提示':r.hints?`已打开 ${r.hints} / 3 个提示`:'按自己的节奏来'}</span><button class="secondary" data-action="hint" ${!canGuide||r.hints>=3?'disabled':''}>${r.hints>=3?'已显示全部提示':r.hints?'再看一个提示':'给我一点提示'}</button></div>`:''}</aside></div><p class="workspace-note">学习记录仅保存在本浏览器 · 原始错误会进入错题记录 · 原创示例，非教材同步</p></div>`,true);
 if(guideTab==='video')mountVideo(practiceViewKey);
}
function complete(){const s=session;setView(`<div class="learning-workspace completion-workspace">${workspaceHeading(subjects[s.subject].label+' · 本次练习','两道题都完成了，给自己的尝试点个赞。')}<div class="workspace-grid"><section class="question-card work-question"><div class="question-content completion-intro"><div class="complete-badge" aria-hidden="true">✓</div><p class="eyebrow">ONE SMALL STEP FOR TODAY</p><h2>又往前走了一小步。</h2><p>会思考、会求助，<br>都是学习的一部分。</p></div></section><aside class="guide-pane"><div class="guide-content"><h2>这一次的小结</h2><div class="summary">${s.records.map((r,i)=>`<div class="summary-row"><strong>${i?'第二题 · 试一道新题':'第一题 · 先自己试试'}</strong><span>${r.firstCorrect?'首次答对':'尝试后答对'} · ${r.hints?`查看 ${r.hints} 个提示`:'未用提示'}</span></div>`).join('')}</div><p class="muted">这只是本次体验的小结，不代表已经掌握。慢慢来，再试一组也可以。</p></div><div class="guide-actions completion-actions"><button class="primary" data-action="home">再选一科 →</button><button class="secondary" data-action="restart">重新体验这一组</button></div></aside></div><p class="workspace-note">小结已保存在当前档案 · 仅此浏览器可见 · 不跨设备同步</p></div>`,true);}
function dateLabel(value){return new Date(value).toLocaleString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});}
function top(title,desc){return `<div class="page-heading"><a class="back" href="#">← 选科首页</a><h1>${title}</h1><p>${desc}</p></div>`;}
function renderVideo(){setView(`<div class="learning-workspace video-workspace">${workspaceHeading('平均分 · 视频讲解','约 1 分钟 · 普通话配音 + 字幕')}<div class="standalone-video-grid"><section class="video-player-card" aria-label="平均分视频与播放控制">${videoMarkup()}</section><aside class="guide-pane video-companion"><div class="guide-content"><span class="chip">原创数学动画</span><h2>怎样分得一样多？</h2><p>12 颗糖，平均分给 3 个小朋友。跟着动画，一步一步分。</p><div class="hint"><strong>带着问题看</strong><p>如果换成 18 颗糖，还是分给 3 人，每人会得到几颗？</p></div><p class="muted">可随时暂停、回看。不自动标记学习完成，也不替换已有练习进度。</p></div><div class="guide-actions"><button class="primary" data-subject="math">去做数学练习 →</button><a class="back" href="#assessments">试试原创单元测评</a></div></aside></div><p class="workspace-note">原创示例 · 视频不是教材同步课程 · 练习记录仅保存在本浏览器</p></div>`,true);mountVideo();}
function renderAssessments(){const p=currentProfile(store),t=p.activeTest;setView(`${top('原创示例单元测评','每单元 4 道不同的题。作答时没有提示，全部交卷后才显示答案和解析。非上海教材同步，不代表正式掌握程度。')}${t?`<div class="flow-note"><strong>${subjects[t.subject].label} · ${units[t.subject].title} ${t.completedAt?'已交卷':'进行中'}</strong><button class="secondary" data-action="continue-test">${t.completedAt?'查看结果':'继续作答'}</button></div>`:''}<div class="subjects">${Object.entries(units).map(([k,u])=>`<button class="subject ${k}" data-test="${k}"><span class="symbol">${subjects[k].symbol}</span><h3>${subjects[k].label} · ${u.title}</h3><p>原创示例单元 · 4 题</p><span class="arrow">→</span></button>`).join('')}</div><p class="privacy-note">正在作答的测评会在本浏览器保存，刷新可继续。开始新测评前会请你确认是否替换未交卷的作答。</p>`);}
function questionNavigation(items,index,answered,attribute){return `<div class="question-navigation" role="group" aria-label="题号导航">${items.map((item,i)=>{const result=attribute==='data-result-page',done=answered(i),status=result?(item.correct?'答对了':'再练一练'):(done?'已作答':'未作答');return `<button class="question-number ${i===index?'current':''} ${done?'answered':''} ${result&&!item.correct?'needs-review':''}" ${attribute}="${i}" aria-label="第 ${i+1} 题，${status}" aria-current="${i===index?'step':'false'}"><span>${i+1}</span>${done?`<small aria-hidden="true">${result&&!item.correct?'·':'✓'}</small>`:''}</button>`;}).join('')}</div>`;}
function renderTest(){
 const t=currentProfile(store).activeTest;if(!t){renderAssessments();return;}if(testResults(t)){renderResults(t);return;}
 const list=units[t.subject].items,index=testCursor(t),q=list[index],count=t.answers.filter(a=>a!==null).length;
 setView(`<div class="learning-workspace assessment-workspace">${workspaceHeading(subjects[t.subject].label+' · '+units[t.subject].title,`原创示例单元 · 第 ${index+1} / ${list.length} 题`,'<a class="back" href="#assessments">← 单元测评</a>')}<div class="workspace-grid"><section class="question-card work-question assessment-question"><div class="question-content"><div class="question-meta"><span class="chip">独立作答</span><span>第 ${index+1} / ${list.length} 题</span></div><h2 class="question-title" tabindex="-1">${esc(q.question)}</h2><p class="instruction">选好后可切换题目，交卷前都能修改。</p><div class="choices" role="group" aria-label="第 ${index+1} 题答案">${q.choices.map((c,j)=>`<button class="choice ${t.answers[index]===c?'selected':''}" data-test-index="${index}" data-test-choice="${esc(c)}" aria-pressed="${t.answers[index]===c}"><span>${String.fromCharCode(65+j)}</span><strong>${esc(c)}</strong></button>`).join('')}</div></div><div class="question-actions assessment-paging"><button class="secondary" data-test-page="${index-1}" ${index===0?'disabled':''}>← 上一题</button><span>${index+1} / ${list.length}</span><button class="primary" data-test-page="${index+1}" ${index===list.length-1?'disabled':''}>下一题 →</button></div></section><aside class="guide-pane assessment-overview"><div class="guide-content"><h2>这次的 4 道题</h2><p class="assessment-progress" role="status">已选 ${count} / ${list.length} 题${testMessage?' · '+esc(testMessage):''}</p>${questionNavigation(list,index,i=>t.answers[i]!==null,'data-test-page')}<p class="muted">点题号可以检查或修改答案。</p><div class="hint"><strong>按自己的节奏完成</strong><p>没有倒计时。全部交卷后，才会显示答案和解析。</p></div><p class="local-notice">刷新或离开会保留答案和当前题目。</p></div><div class="guide-actions"><span>${count===list.length?'都选好啦，也可以先回看一下。':`还有 ${list.length-count} 题未作答`}</span><button class="primary" data-action="submit-test" ${count!==list.length?'disabled':''}>交卷并看解析</button></div></aside></div><p class="workspace-note">非上海教材同步 · 不代表正式掌握程度 · 交卷后无法修改本次答案</p></div>`,true);
}
function renderResults(t,index=0){
 const results=testResults(t);if(!results)return;resultTest=t;resultIndex=Math.min(results.length-1,Math.max(0,index));const r=results[resultIndex],score=results.filter(r=>r.correct).length;
 setView(`<div class="learning-workspace results-workspace">${workspaceHeading('这次测评的小结',subjects[t.subject].label+' · '+units[t.subject].title+' · 原创示例单元','<a class="back" href="#assessments">← 单元测评</a>')}<div class="workspace-grid"><section class="question-card work-question"><div class="question-content"><div class="question-meta"><span class="chip">第 ${resultIndex+1} 题 · ${r.correct?'答对了':'再练一练'}</span></div><h2 class="question-title" tabindex="-1">${esc(r.question)}</h2><div class="answer-review"><p>你的选择：<strong>${esc(r.chosen)}</strong></p><p>正确答案：<strong>${esc(r.answer)}</strong></p></div><div class="feedback good"><strong>解题思路</strong>${esc(r.explanation)}</div></div><div class="question-actions assessment-paging"><button class="secondary" data-result-page="${resultIndex-1}" ${resultIndex===0?'disabled':''}>← 上一题</button><span>${resultIndex+1} / ${results.length}</span><button class="primary" data-result-page="${resultIndex+1}" ${resultIndex===results.length-1?'disabled':''}>下一题 →</button></div></section><aside class="guide-pane"><div class="guide-content"><div class="result-banner"><strong>${score} / ${results.length} 题答对</strong><p>${dateLabel(t.completedAt)}</p><p>错题已保留到当前档案。</p></div>${questionNavigation(results,resultIndex,()=>true,'data-result-page')}<p class="muted">点题号，逐题看看解析。这个结果不用于判断正式掌握程度。</p></div><div class="guide-actions"><button class="primary" data-test="${t.subject}">开始新一轮</button><a class="secondary" href="#wrongs">去错题记录</a></div></aside></div><p class="workspace-note">本次答案已交卷 · 原始错误与订正记录分别保留 · 仅此浏览器可见</p></div>`,true);
}
function renderWrongs(){const p=currentProfile(store);if(retryId){renderRetry();return;}setView(`${top('错题记录',`学习档案 ${store.current} · 基础两题练习 / 测评：${p.wrongs.length} 次原始错误；${p.wrongs.filter(r=>!r.correctedAt).length} 次待订正。同一道题多次答错会分别保留。`)}${loopWrongsMarkup(p)}${!p.wrongs.length?'<div class="empty-state"><h2>基础练习 / 测评暂无错题</h2><p>练习或单元测评中答错的题目会出现在这里。</p><a class="secondary" href="#">去试一道题</a></div>':p.wrongs.slice().reverse().map(r=>`<article class="question-card wrong-card"><div class="question-meta"><span class="chip">${r.correctedAt?'已订正':'待订正'}</span><span>${esc(r.source)} · ${dateLabel(r.date)}</span></div><h2>${esc(questionById(r.qid).question)}</h2><p>原来选择：<strong>${r.chosen===null?'我还不会':esc(r.chosen)}</strong> · 正确答案：<strong>${esc(r.expected)}</strong></p>${r.correctedAt?`<p class="muted">订正于 ${dateLabel(r.correctedAt)}，原始错误仍保留。</p>`:''}<button class="secondary" data-retry="${esc(r.id)}">${r.correctedAt?'再巩固一次':'再试一次，完成订正'}</button></article>`).join('')}`);}
function renderRetry(){const r=currentProfile(store).wrongs.find(r=>r.id===retryId);if(!r){retryId=null;renderWrongs();return;}const q=questionById(r.qid);setView(`<div class="learning-workspace retry-workspace">${workspaceHeading('再试一次','独立选一个答案，答对后标记已订正。','<button class="back" data-action="close-retry">← 返回错题记录</button>')}<div class="workspace-grid"><section class="question-card work-question"><div class="question-content"><div class="question-meta"><span class="chip">错题订正</span><span>${esc(r.source)}</span></div><h2 class="question-title" tabindex="-1">${esc(q.question)}</h2><p class="instruction">慢慢想一想，再选一次。</p><div class="choices" role="group" aria-label="订正答案">${q.choices.map((c,i)=>`<button class="choice ${retryChoice===c?'selected':''}" data-retry-choice="${esc(c)}" aria-pressed="${retryChoice===c}" ${retryFeedback===true?'disabled':''}><span>${String.fromCharCode(65+i)}</span><strong>${esc(c)}</strong></button>`).join('')}</div>${retryFeedback!==null?`<div class="feedback ${retryFeedback?'good':''}" role="status"><strong>${retryFeedback?'已订正！':'再想一想，可以换一个答案试试。'}</strong></div>`:''}</div><div class="question-actions"><button class="secondary" data-action="close-retry">返回记录</button><button class="primary" data-action="check-retry" ${retryChoice===null||retryFeedback===true?'disabled':''}>检查订正答案</button></div></section><aside class="guide-pane"><div class="guide-content"><span class="guide-symbol" aria-hidden="true">${retryFeedback?'✓':'↻'}</span><h2>${retryFeedback?'这次的解题思路':'给自己一次新尝试'}</h2><p>${retryFeedback?esc(q.explanation):'先独立想一想，检查答案后再看看解题思路。'}</p><p class="muted">订正不会删除原始错误。每一次尝试，都能留下进步的脚印。</p></div></aside></div><p class="workspace-note">订正记录只保存在当前浏览器 · 原始错误不会删除</p></div>`,true);}
function renderParent(notice=''){const p=currentProfile(store),attempts=Object.values(p.practices).reduce((n,s)=>n+s.records.reduce((a,r)=>a+r.attempts,0),0);setView(`${top('家长小结',`学习档案 ${store.current} · 只展示此浏览器保存的记录，不推断年级、能力或掌握程度。`)}${backupMarkup()}<div class="stats-grid"><div><strong>${p.practiceCompleted.length}</strong><span>基础两题练习完成组</span></div><div><strong>${p.assessments.length}</strong><span>已交卷的测评</span></div><div><strong>${p.wrongs.length+loopEvidence(p).reduce((n,r)=>n+r.wrongs.length,0)}</strong><span>原始未答对次数（含不会）</span></div><div><strong>${p.wrongs.filter(r=>!r.correctedAt).length}</strong><span>基础练习 / 测评待订正</span></div></div>${loopParentMarkup(p)}<h2>练习记录</h2>${p.practiceCompleted.length?`<div class="summary">${p.practiceCompleted.slice().reverse().map(r=>`<div class="summary-row"><strong>${subjects[r.subject].label} · 2 题完成</strong><span>${r.records.filter(x=>x.firstCorrect).length} 题首次答对 · ${dateLabel(r.date)}</span></div>`).join('')}</div>`:'<p class="empty-state">基础两题练习尚无完成记录。完成两道基础练习题后，这里会出现小结。</p>'}<p class="local-notice">当前保留的各科练习共有 ${attempts} 次作答（含“我还不会”）。重新开始某科后，该科当前作答次数从头计；已完成小结与原始错题保留。</p><h2>历次测评</h2>${p.assessments.length?`<div class="summary">${p.assessments.slice().reverse().map(t=>`<div class="summary-row"><div><strong>${subjects[t.subject].label} · ${units[t.subject].title}</strong><br><span>${testResults(t).filter(r=>r.correct).length} / ${t.answers.length} 题答对 · ${dateLabel(t.completedAt)}</span></div><button class="secondary" data-history="${esc(t.id)}">查看解析</button></div>`).join('')}</div>`:'<p class="empty-state">还没有已交卷的测评，不显示示例历史。</p>'}<a class="secondary" href="#wrongs">查看错题与订正</a><p class="privacy-note">档案 A / B 不是账号，使用同一浏览器的人都可以切换查看。</p>`);if(storageBlocked)return;disposeBackup=mountBackup(main,{getStore:()=>store,notice,scope:window,commitStore:next=>{if(!canAct())throw Object.assign(new Error('BACKUP_STORE_CHANGED'),{code:'BACKUP_STORE_CHANGED'});persistBackupRestore(storage,store,next);store=next;session=null;retryId=null;warning='';},onRestored:text=>{renderProfile();renderParent(text);main.querySelector('#backup-status')?.focus({preventScroll:false});}});}
function renderLoop(subject,kind='practice'){const p=currentProfile(store);const r=startLoop(p,subject,{kind});if(!r){setView(reviewMarkup(p));return;}persist();setView(loopMarkup(r),true);}
function renderDialogue(questionId){setView(dialogueMarkup(questionId),true);if(storageBlocked)return;disposeDialogue=mountDialogue(main,questionId);}
function route(){if(!canAct())return;disposeDialogue?.();disposeDialogue=null;disposeVideo?.();disposeVideo=null;renderProfile();const key=location.hash.slice(1);document.querySelectorAll('.main-nav a').forEach(a=>a.setAttribute('aria-current',a.getAttribute('href')===(location.hash||'#')?'page':'false'));if(key!=='wrongs')retryId=null;if(parseDialogueRoute(key)){renderDialogue(parseDialogueRoute(key));}else if(key.startsWith('loop/')&&isLoopSubject(key.slice(5))){renderLoop(key.slice(5));}else if(key.startsWith('review/')&&isLoopSubject(key.slice(7))){renderLoop(key.slice(7),'review');}else if(key==='reviews'){setView(reviewMarkup(currentProfile(store)));}else if(subjects[key]){session=getPractice(store,key);session.complete?complete():renderPractice();}else if(key==='video')renderVideo();else if(key==='assessments')renderAssessments();else if(key==='test')renderTest();else if(key==='wrongs')renderWrongs();else if(key==='parent')renderParent();else home();}
function goHome(){if(!canAct())return;location.hash='';route();focusMain();}
function askLeave(){goHome();}
main.addEventListener('click',event=>{if(!canAct()){event.preventDefault?.();event.stopImmediatePropagation?.();return;}const b=event.target.closest('button');if(!b||b.disabled)return;
if(b.dataset.loopAction){if(loopAction(currentProfile(store),b.dataset.loopId,Number(b.dataset.loopRevision),b.dataset.loopAction,b.dataset.loopValue??null)){persist();const r=currentProfile(store).learningLoop.runs.find(r=>r.id===b.dataset.loopId);setView(loopMarkup(r),true);const target=b.dataset.loopAction==='select'?'[data-loop-action="select"][aria-pressed="true"]':b.dataset.loopAction==='guide'?'[data-loop-action="next"]':'.question-title';main.querySelector(target)?.focus({preventScroll:true});}return;}
if(b.dataset.loopRestart){startLoop(currentProfile(store),b.dataset.loopRestart,{restart:true});persist();location.hash='loop/'+b.dataset.loopRestart;route();focusMain();return;}
if(b.dataset.loopReview){const p=currentProfile(store),r=getLoop(p,b.dataset.loopReview,'review');startLoop(p,b.dataset.loopReview,{kind:'review',restart:!!r?.completedAt});persist();location.hash='review/'+b.dataset.loopReview;route();focusMain();return;}
if(b.dataset.subject){session=getPractice(store,b.dataset.subject);persist();location.hash=b.dataset.subject;route();focusMain();return;}
if(b.dataset.test){const t=currentProfile(store).activeTest;if(t&&!t.completedAt){pendingTest=b.dataset.test;document.querySelector('#replace-test').showModal();}else{startTest(store,b.dataset.test);persist();location.hash='test';route();focusMain();}return;}
if(b.dataset.guide){if(b.dataset.guide==='video'&&(session?.subject!=='math'||!session.records[session.stage].attempts))return;guideTab=b.dataset.guide;renderPractice();main.querySelector(`[data-guide="${guideTab}"]`)?.focus({preventScroll:true});return;}
if(b.dataset.testPage!==undefined){if(navigateTest(store,Number(b.dataset.testPage))){persist();renderTest();main.querySelector('.question-title')?.focus({preventScroll:true});}return;}
if(b.dataset.resultPage!==undefined){const index=Number(b.dataset.resultPage);if(resultTest&&Number.isInteger(index)&&index>=0&&index<units[resultTest.subject].items.length){renderResults(resultTest,index);main.querySelector('.question-title')?.focus({preventScroll:true});}return;}
if(b.dataset.testIndex!==undefined){chooseTest(store,Number(b.dataset.testIndex),b.dataset.testChoice);persist();renderTest();main.querySelector(`[data-test-index="${b.dataset.testIndex}"][data-test-choice="${CSS.escape(b.dataset.testChoice)}"]`)?.focus({preventScroll:true});return;}
if(b.dataset.history){const t=currentProfile(store).assessments.find(t=>t.id===b.dataset.history);if(t)renderResults(t);focusMain();return;}
if(b.dataset.retry){retryId=b.dataset.retry;retryChoice=null;retryFeedback=null;renderRetry();focusMain();return;}
if(b.dataset.retryChoice!==undefined){retryChoice=b.dataset.retryChoice;retryFeedback=null;renderRetry();main.querySelector(`[data-retry-choice="${CSS.escape(retryChoice)}"]`)?.focus({preventScroll:true});return;}
if(b.dataset.choice!==undefined){if(select(session,b.dataset.choice)){persist();renderPractice();main.querySelector(`[data-choice="${CSS.escape(b.dataset.choice)}"]`)?.focus({preventScroll:true});}return;}
const action=b.dataset.action;
if(action==='close-retry'){retryId=null;renderWrongs();focusMain();return;}
if(action==='check-retry'){retryFeedback=retryWrong(store,retryId,retryChoice);persist();renderRetry();return;}
if(action==='continue-test'){location.hash='test';route();focusMain();return;}
if(action==='submit-test'){if(submitTest(store)){persist();renderTest();focusMain();}return;}
if(action==='leave'||action==='home'){goHome();return;}
if(action==='restart'){session=getPractice(store,session.subject,true);persist();renderPractice();focusMain();return;}
if(action==='submit'||action==='skip'){if(practiceAttempt(store,session,action==='skip')){guideTab='hints';persist();renderPractice();main.querySelector(session.records[session.stage].solved?'[data-action="next"]':'[data-action="hint"]')?.focus({preventScroll:true});}}
if(action==='hint'){if(hint(session)){persist();renderPractice();main.querySelector('[data-action="hint"]')?.focus({preventScroll:true});}}
if(action==='next'&&advance(session)){finishPractice(store,session);persist();route();focusMain();}
},true);
document.querySelector('#profile-controls').addEventListener('click',event=>{if(!canAct()){event.preventDefault?.();event.stopImmediatePropagation?.();return;}const b=event.target.closest('button');if(!b)return;if(b.hasAttribute?.('data-open-info')){info.showModal();return;}if(b.dataset.profile){switchProfile(store,b.dataset.profile);session=null;retryId=null;persist();route();focusMain();}if(b.id==='clear-profile'){document.querySelector('#clear-label').textContent=`学习档案 ${store.current}`;document.querySelector('#clear-confirm').showModal();}});
document.querySelector('#confirm-clear').addEventListener('click',()=>{if(!canAct())return;clearProfile(store);session=null;retryId=null;persist();document.querySelector('#clear-confirm').close();goHome();});
document.querySelector('#confirm-replace').addEventListener('click',()=>{if(!canAct())return;if(pendingTest){startTest(store,pendingTest);pendingTest=null;persist();}document.querySelector('#replace-test').close();location.hash='test';route();focusMain();});
document.querySelector('.brand').addEventListener('click',e=>{e.preventDefault();askLeave();});
document.querySelector('#about').addEventListener('click',()=>{if(canAct())info.showModal();});
document.querySelectorAll('[data-close-dialog]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));
window.addEventListener('storage',event=>coordinator.handleStorageEvent(event));
for(const type of ['change','submit'])main.addEventListener(type,event=>{if(!canAct()){event.preventDefault?.();event.stopImmediatePropagation?.();}},true);
const conflict=document.querySelector('#storage-conflict');
conflict.addEventListener('cancel',event=>{if(storageBlocked&&!reloading){event.preventDefault();showStorageConflict();}});
conflict.addEventListener('close',()=>{if(storageBlocked&&!reloading)showStorageConflict();});
for(const profileId of ['A','B'])document.querySelector('#storage-backup-'+profileId).addEventListener('click',()=>{
 if(!storageBlocked||reloading)return;
 const status=document.querySelector('#storage-conflict-status');
 try{downloadBackupFile(exportProfileBackup(store,profileId),{scope:window});status.textContent=`已发起档案 ${profileId} 的本地临时备份下载。请确认文件已保存；它不包含另一页面的新记录。`;}
 catch{status.textContent='未能发起临时备份下载，本页记录未改动。请先保留本页，不要急于重新载入。';}
});
document.querySelector('#storage-reload').addEventListener('click',()=>{if(!storageBlocked||reloading)return;reloading=true;try{location.reload();}catch{reloading=false;document.querySelector('#storage-conflict-status').textContent='未能重新载入。请先确认临时备份已保管，再使用浏览器刷新。';}});
conflictReady=true;if(storageBlocked)showStorageConflict();
window.addEventListener('hashchange',()=>{route();focusMain();});route();

main.addEventListener('keydown',event=>{if(!canAct()){event.preventDefault?.();event.stopImmediatePropagation?.();return;}const tab=event.target.closest('[data-guide]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;const tabs=[...main.querySelectorAll('[data-guide]:not(:disabled)')];if(tabs.length<2)return;event.preventDefault();const index=tabs.indexOf(tab),next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(index+(event.key==='ArrowLeft'?-1:1)+tabs.length)%tabs.length;tabs[next].click();},true);
window.addEventListener('pagehide',()=>{disposeBackup?.();disposeBackup=null;disposeDialogue?.();disposeDialogue=null;disposeVideo?.();disposeVideo=null;});
window.addEventListener('pageshow',event=>{if(event.persisted)route();});
